  const getRect = (el) => {
    if (!el) return null;
    const r = el.getBoundingClientRect();
    return { x: r.x, y: r.y, width: r.width, height: r.height, top: r.top, left: r.left, bottom: r.bottom, right: r.right };
  };

  const btn = document.querySelector('[class*="slide-btn"], [class*="handlebar"], [class*="slider"] button, [class*="slider"] div');
  const img = document.querySelector('img');
  const canvases = Array.from(document.querySelectorAll('canvas')).map(c => ({
    rect: getRect(c),
    width: c.width,
    height: c.height,
