const tabId = 2126149062;
const pieceAnalysis = await browserjs(tabId, () => {
  const img = document.querySelector('.slider-img-bg-1konc');
  const canvas = document.createElement('canvas');
  canvas.width = img.naturalWidth;
  canvas.height = img.naturalHeight;
  const ctx = canvas.getContext('2d');
  ctx.drawImage(img, 0, 0);
  const data = ctx.getImageData(0, 0, canvas.width, canvas.height).data;

  // Find columns where piece is located (look at left 80 pixels)
  // The piece has a bright or semi-transparent outline
  const colScores = [];
  for (let x = 0; x < 80; x++) {
    let diff = 0;
    for (let y = 10; y < canvas.height - 10; y++) {
      const idx = (y * canvas.width + x) * 4;
      // check white pixels (piece has white/bright overlay)
      if (data[idx] > 200 && data[idx+1] > 200 && data[idx+2] > 200) {
        diff++;
      }
    }
    colScores.push(diff);
  }
  return colScores;
});
console.log("Piece col scores:", pieceAnalysis);

