const tabId = 2126149062;
const holeScores = await browserjs(tabId, () => {
  const img = document.querySelector('.slider-img-bg-1konc');
  const canvas = document.createElement('canvas');
  canvas.width = img.naturalWidth;
  canvas.height = img.naturalHeight;
  const ctx = canvas.getContext('2d');
  ctx.drawImage(img, 0, 0);
  const data = ctx.getImageData(0, 0, canvas.width, canvas.height).data;

  const colDark = [];
  for (let x = 180; x < 280; x++) {
    let darkCount = 0;
    for (let y = 10; y < canvas.height - 10; y++) {
      const idx = (y * canvas.width + x) * 4;
      // dark pixel in hole: r < 50, g < 50, b < 50
      if (data[idx] < 50 && data[idx+1] < 50 && data[idx+2] < 50) {
        darkCount++;
      }
    }
    colDark.push({ x, darkCount });
  }
  return colDark.filter(c => c.darkCount > 10);
});
console.log("Hole dark columns:", holeScores);
const holeStart = holeScores[0]?.x;
const holeEnd = holeScores[holeScores.length - 1]?.x;
console.log(`Hole is from x=${holeStart} to x=${holeEnd}, width=${holeEnd - holeStart}`);
const holeCenter = (holeStart + holeEnd) / 2;
const pieceCenter = 29.5;
console.log(`Distance in natural pixels = ${holeCenter - pieceCenter}`);
const scale = 250 / 320;
console.log(`Distance in display pixels = ${(holeCenter - pieceCenter) * scale}`);

