const tabId = 2126149123;
// Wait for product cards to appear or inspect the DOM
await tool.wait_for({ tabId, condition: "selector_visible", value: "#search-results, [data-qa='search-result-item'], li a[href*='/product/']", timeout_ms: 10000 });

const reiProducts = await browserjs(tabId, () => {
  const items = Array.from(document.querySelectorAll('li a[href*="/product/"]')).map(a => {
    const parent = a.closest('li');
    return {
      href: a.href,
      title: parent?.querySelector('span[data-ui="product-title"], [class*="title"], h2')?.textContent?.trim() || a.textContent?.trim(),
      price: parent?.querySelector('[data-ui="sale-price"], [data-ui="price"], span[class*="price"]')?.textContent?.trim(),
      rating: parent?.querySelector('[class*="rating"], [aria-label*="star"]')?.getAttribute('aria-label') || parent?.querySelector('[class*="rating"]')?.textContent?.trim()
    };
  });
  // remove duplicates
  const unique = [];
  const seen = new Set();
  for (const item of items) {
    if (item.href && !seen.has(item.href) && item.title) {
      seen.add(item.href);
      unique.push(item);
    }
  }
  return unique;
});
console.log("REI products count:", reiProducts.length);
console.log("REI products:", JSON.stringify(reiProducts.slice(0, 10), null, 2));

