const amzProducts = await browserjs(tabId, () => {
  const items = Array.from(document.querySelectorAll('[data-component-type="s-search-result"]')).map(el => {
    const titleEl = el.querySelector('h2 a span, h2 span');
    const linkEl = el.querySelector('h2 a');
    const priceWhole = el.querySelector('.a-price-whole')?.textContent?.trim();
    const priceFraction = el.querySelector('.a-price-fraction')?.textContent?.trim();
