    const rating = el.querySelector('.a-icon-alt')?.textContent?.trim();
    const reviewCount = el.querySelector('span[aria-label*="ratings"], .a-size-small .a-link-normal span')?.textContent?.trim();

    return {
      title: titleEl?.textContent?.trim(),
      href: linkEl?.href,
      price,
      rating,
      reviewCount
    };
  }).filter(x => x.title && x.price);

  return items;
});
