const tabId = 2126149123;
const wmItems = await browserjs(tabId, () => {
  const items = Array.from(document.querySelectorAll('[data-item-id], [data-testid="item-stack"] > div, div[class*="sans-serif"]')).map(el => {
    const title = el.querySelector('[data-automation-id="product-title"], span[class*="normal"]')?.textContent?.trim();
    const price = el.querySelector('[data-automation-id="product-price"], [class*="w_iUH7"]')?.textContent?.trim();
    const link = el.querySelector('a[href*="/ip/"]')?.href;
    const rating = el.querySelector('[data-testid="product-ratings"], [class*="rating"]')?.textContent?.trim();
    return { title, price, link, rating };
  }).filter(x => x.title && x.price && x.link && x.title.toLowerCase().includes('towel'));

  // deduplicate
  const unique = [];
  const seen = new Set();
  for (const item of items) {
    if (!seen.has(item.link)) {
      seen.add(item.link);
      unique.push(item);
    }
  }
  return unique;
});
